// Comprehensive validation of the marketing job against spec v3.5
const job = $('Execute Workflow Trigger').first().json;
const reg = $('Lookup Business Drive Registry').first().json || {};
const listings = $('Read Listings Sheet').all().map(i => i.json);

const errors = [];

// 1. Business Status Check
if (!job.business_id || job.business_status !== 'Active') {
  errors.push(`Business '${job.business_name || 'unknown'}' is not Active (Status: ${job.business_status || 'missing'}).`);
}

// 2. Drive Registry Provisioning Check
if (!reg.root_drive_id || reg.provisioning_status !== 'COMPLETED') {
  errors.push(`Business Drive folder structure not provisioned. Run WF-00 first.`);
}

// 3. Marketing Job, Content Format, and Prompt Template Checks
if (!job.marketing_job || !job.marketing_job.trim()) {
  errors.push('Marketing Job name is required.');
}

const allowedFormats = ['Reel', 'Static Image', 'Story', 'Carousel'];
if (!job.content_format || !allowedFormats.includes(job.content_format)) {
  errors.push(`Invalid or missing Content Format '${job.content_format}'. Must be one of: ${allowedFormats.join(', ')}.`);
}

if (!job.prompt_template || !job.prompt_template.trim()) {
  errors.push('Prompt Template is required.');
}

// 4. Listing Check if Content Focus = Listing
let resolvedListing = null;
if (job.content_focus && job.content_focus.trim().toLowerCase() === 'listing') {
  if (!job.selected_listing || !job.selected_listing.trim()) {
    errors.push("Content Focus is 'Listing' but Selected Listing is blank.");
  } else {
    const match = listings.find(l => 
      String(l['Listing Name'] || '').trim().toLowerCase() === job.selected_listing.trim().toLowerCase() ||
      String(l['Listing ID'] || '').trim().toLowerCase() === job.selected_listing.trim().toLowerCase()
    );
    if (!match) {
      errors.push(`Selected Listing '${job.selected_listing}' not found in Listings sheet.`);
    } else if (String(match.Active).toUpperCase() !== 'TRUE') {
      errors.push(`Selected Listing '${job.selected_listing}' is not marked Active in Listings sheet.`);
    } else {
      resolvedListing = match;
    }
  }
}

// 5. State Check: verify internal job is not already finished or in terminal state
const invalidTerminalStates = ['Ready to Schedule', 'Schedule Requested', 'Scheduled', 'Publish Confirmed', 'Published'];
if (invalidTerminalStates.includes(job.scheduling_status)) {
  errors.push(`Job already in advanced scheduling state: '${job.scheduling_status}'.`);
}

const isValid = errors.length === 0;

return [{
  json: {
    ...job,
    is_valid: isValid,
    validation_errors: errors,
    registry_info: reg,
    resolved_listing: resolvedListing,
    validated_at: new Date().toISOString()
  }
}];
